{"code":"def transform(g):
    # mark turn/corner cells: closed rectangular turns are 4; turns belonging
    # to non-closed traces are 2. Preserve everything else.
    h,w=len(g),len(g[0]); out=[r[:] for r in g]
    seen=set()
    for i in range(h):
      for j in range(w):
       if g[i][j]!=9 or (i,j) in seen: continue
       st=[(i,j)]; seen.add((i,j)); comp=[]
       while st:
        x,y=st.pop(); comp.append((x,y))
        for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
         a,b=x+dx,y+dy
         if 0<=a<h and 0<=b<w and g[a][b]==9 and (a,b) not in seen: seen.add((a,b));st.append((a,b))
       S=set(comp)
       # closed if every cell has two or more neighbors (ring-like outline)
       closed=all(sum((x+dx,y+dy) in S for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)))>=2 for x,y in comp)
       for x,y in comp:
        n=sum((x+dx,y+dy) in S for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)))
        if n==2:
         ds=sum((x+dx,y+dy) in S for dx,dy in ((1,1),(1,-1),(-1,1),(-1,-1)))
         if ds==0: out[x][y]=4 if closed else 2
    return out"}

